import{_ as d,o as e,c as a,a6 as r}from"./chunks/framework.B_q3ZJNF.js";const f=JSON.parse('{"title":"mini-ORM 与真实 ORM 差异清单","description":"","frontmatter":{"title":"mini-ORM 与真实 ORM 差异清单"},"headers":[],"relativePath":"sql-orm-course/orm-divergence.md","filePath":"sql-orm-course/docs/orm-divergence.md"}'),o={name:"sql-orm-course/orm-divergence.md"};function h(i,t,n,l,s,m){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="mini-orm-与真实-orm-差异清单" tabindex="-1">mini-ORM 与真实 ORM 差异清单 <a class="header-anchor" href="#mini-orm-与真实-orm-差异清单" aria-label="Permalink to &quot;mini-ORM 与真实 ORM 差异清单&quot;">​</a></h1><p>全书正文每处「本课程简化为 … / 不做 …」的集中登记。分两栏：<strong>简化项</strong>（做了但比真实 ORM 简化）与<strong>未实现项</strong>（真实 ORM 有、mini-ORM 没做），另附一节<strong>实验场环境类简化</strong>（不是 ORM 的差距，是教学环境的取舍）。逐条的完整原理见<a href="./14-finale-gaps.html">第 14 章</a>的对账。</p><h2 id="简化项" tabindex="-1">简化项 <a class="header-anchor" href="#简化项" aria-label="Permalink to &quot;简化项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>简化项</th><th>mini-ORM 的做法</th><th>真实 ORM 的做法</th><th>正文出处</th></tr></thead><tbody><tr><td>类型映射</td><td>schema 只认 <code>integer / text / real</code>；布尔、日期不映射，存取自己换算</td><td>Prisma 的 <code>Boolean</code>、TypeORM 的 <code>boolean</code> 列自动换 0/1；日期有专门列类型</td><td><a href="./09-schema-to-ddl.html">第 9 章</a></td></tr><tr><td>命名映射</td><td>字段名与列名保持同名</td><td>Prisma <code>@map</code> / <code>@@map</code>、TypeORM <code>namingStrategy</code> 做 userName ↔ user_name 自动映射</td><td><a href="./09-schema-to-ddl.html">第 9 章</a>、<a href="./11-hydration-dirty-tracking.html">第 11 章</a></td></tr><tr><td>查询条件</td><td>where 只支持 AND 叠加，七个比较操作符 + LIKE</td><td>各家支持 OR 分组、<code>In</code> / <code>Between</code> / <code>Not</code> 等操作符（TypeORM FindOptions、Prisma <code>where OR</code>）</td><td><a href="./10-query-builder.html">第 10 章</a>、<a href="./12-relations-n-plus-1.html">第 12 章</a></td></tr><tr><td>聚合进构建器</td><td>聚合函数与分组不进构建器，要聚合直接写 SQL</td><td>各家查询层支持 count/aggregate</td><td><a href="./10-query-builder.html">第 10 章</a></td></tr><tr><td>关联加载顺序</td><td>两跳加载不额外排序，顺序不保证</td><td>各家支持关联的 orderBy</td><td><a href="./12-relations-n-plus-1.html">第 12 章</a></td></tr><tr><td>隔离语义</td><td>只讲「同连接自见未提交、他连接不可见」一句话</td><td>完整隔离级别（READ COMMITTED 等）可配</td><td><a href="./13-transactions.html">第 13 章</a></td></tr></tbody></table><h2 id="未实现项" tabindex="-1">未实现项 <a class="header-anchor" href="#未实现项" aria-label="Permalink to &quot;未实现项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>未实现项</th><th>为什么没做</th><th>真实 ORM 怎么做</th><th>正文出处</th></tr></thead><tbody><tr><td>类型推导</td><td>schema 不生成 TS 类型，行/关联的类型是 <code>unknown</code>，接口手写</td><td>Prisma 由 schema 生成 client 类型；Drizzle 按表定义自动推断（含可空性）；TypeORM 装饰器 + 反射</td><td><a href="./11-hydration-dirty-tracking.html">第 11 章</a>、<a href="./14-finale-gaps.html">第 14 章</a></td></tr><tr><td>乐观锁</td><td>丢更新只靠脏跟踪缓解（只写变化列），根治没做</td><td>版本号/时间戳列（TypeORM <code>@VersionColumn</code> 等），写入时校验版本</td><td><a href="./11-hydration-dirty-tracking.html">第 11 章</a></td></tr><tr><td>IN / BETWEEN 操作符</td><td>构建器白名单未收；两跳加载内部手拼参数化 IN</td><td>查询层原生支持</td><td><a href="./10-query-builder.html">第 10 章</a>、<a href="./12-relations-n-plus-1.html">第 12 章</a></td></tr><tr><td>嵌套关联</td><td>with 不支持嵌套（关联的关联）</td><td>各家支持深层 include / relations</td><td><a href="./12-relations-n-plus-1.html">第 12 章</a></td></tr><tr><td>嵌套事务</td><td>tx 不支持嵌套，直接抛中文错误</td><td>用 SAVEPOINT（保存点）实现嵌套回滚</td><td><a href="./13-transactions.html">第 13 章</a></td></tr><tr><td>多对多 / 透视表</td><td>只有 hasMany / belongsTo</td><td>TypeORM <code>@ManyToMany</code> + <code>@JoinTable</code>、Prisma 隐式关系表，自动建第三张表</td><td><a href="./14-finale-gaps.html">第 14 章</a></td></tr><tr><td>迁移</td><td>表结构只由 defineTable 首次建表</td><td>Prisma Migrate / Drizzle Kit / TypeORM migration：编号迁移文件 + 历史表，两环境重放</td><td><a href="./14-finale-gaps.html">第 14 章</a></td></tr><tr><td>连接池</td><td>SQLite 内存库单连接，无池化必要</td><td>MySQL/PG 驱动层预建连接排队复用（借还纪律、上限、等待队列）</td><td><a href="./14-finale-gaps.html">第 14 章</a></td></tr><tr><td>方言 / 多库</td><td>SQL 生成绑死 SQLite 语法</td><td>各家为 MySQL / PG / SQLite 等分别编译（方言分叉）</td><td><a href="./14-finale-gaps.html">第 14 章</a></td></tr></tbody></table><h2 id="实验场环境类简化" tabindex="-1">实验场环境类简化 <a class="header-anchor" href="#实验场环境类简化" aria-label="Permalink to &quot;实验场环境类简化&quot;">​</a></h2><p>不是 mini-ORM 与真实 ORM 的差距，是教学环境的取舍，一并登记：</p><table tabindex="0"><thead><tr><th>简化项</th><th>实验场的做法</th><th>真实环境的做法</th><th>正文出处</th></tr></thead><tbody><tr><td>内存库</td><td><code>createDb()</code> 打开 <code>:memory:</code>，进程退出即拆</td><td>数据库落盘持久化，数据不随进程消失</td><td><a href="./01-tables-and-rows.html">第 1 章</a></td></tr><tr><td>磁盘成本</td><td>事务性能对比里没有磁盘等待，差距只剩事务开销本身</td><td>提交要等数据真正落盘，逐条提交的差距大一个量级</td><td><a href="./13-transactions.html">第 13 章</a></td></tr></tbody></table><p>另有三处正文声明「不展开」的知识点，不属 ORM 差异，仅备查：外键的 ON DELETE 级联动作（<a href="./03-update-delete-constraints.html">第 3 章</a>）、日期函数与时区（<a href="./04-aggregate-group-by.html">第 4 章</a>）、RIGHT/FULL JOIN（<a href="./05-join-tables.html">第 5 章</a>）。</p>',10)])])}const p=d(o,[["render",h]]);export{f as __pageData,p as default};
